+import { type AnyColumn, Column } from '~/column.ts';
+import { entityKind, is } from '~/entity.ts';
+import { type DriverValueEncoder, SQL, sql, type SQLWrapper } from '../sql.ts';
+
+export function validateWindowName(name: string): void {
+	if (typeof name !== 'string' || name.length === 0) {
+		throw new Error('Window name must be a non-empty string');
+	}
+	if (name.trim().length === 0) {
+		throw new Error('Window name cannot be whitespace-only');
+	}
+}
+
+export type WindowFrameBoundary =
+	| { type: 'unbounded_preceding' }
+	| { type: 'preceding'; offset: number | SQLWrapper }
+	| { type: 'current_row' }
+	| { type: 'following'; offset: number | SQLWrapper }
+	| { type: 'unbounded_following' };
+
+export const unboundedPreceding: WindowFrameBoundary = { type: 'unbounded_preceding' };
+export const currentRow: WindowFrameBoundary = { type: 'current_row' };
+export const unboundedFollowing: WindowFrameBoundary = { type: 'unbounded_following' };
+
+export function preceding(offset: number | SQLWrapper): WindowFrameBoundary {
+	if (typeof offset === 'number') {
+		if (!Number.isInteger(offset) || offset < 0) {
+			throw new Error(`preceding: offset must be a non-negative integer, got ${offset}`);
+		}
+	}
+	return { type: 'preceding', offset };
+}
+
+export function following(offset: number | SQLWrapper): WindowFrameBoundary {
+	if (typeof offset === 'number') {
+		if (!Number.isInteger(offset) || offset < 0) {
+			throw new Error(`following: offset must be a non-negative integer, got ${offset}`);
+		}
+	}
+	return { type: 'following', offset };
+}
+
+function getBoundaryRank(b: WindowFrameBoundary): number | undefined {
+	switch (b.type) {
+		case 'unbounded_preceding':
+			return -Infinity;
+		case 'preceding':
+			return typeof b.offset === 'number' ? -b.offset : undefined;
+		case 'current_row':
+			return 0;
+		case 'following':
+			return typeof b.offset === 'number' ? b.offset : undefined;
+		case 'unbounded_following':
+			return Infinity;
+	}
+}
+
+function formatBoundary(b: WindowFrameBoundary): SQL {
+	switch (b.type) {
+		case 'unbounded_preceding':
+			return sql`unbounded preceding`;
+		case 'current_row':
+			return sql`current row`;
+		case 'unbounded_following':
+			return sql`unbounded following`;
+		case 'preceding':
+			return typeof b.offset === 'number'
+				? sql`${sql.raw(String(b.offset))} preceding`
+				: sql`${b.offset} preceding`;
+		case 'following':
+			return typeof b.offset === 'number'
+				? sql`${sql.raw(String(b.offset))} following`
+				: sql`${b.offset} following`;
+	}
+}
+
+export class WindowFrame implements SQLWrapper {
+	static readonly [entityKind]: string = 'WindowFrame';
+
+	constructor(
+		public type: 'rows' | 'range',
+		public spec: { from: WindowFrameBoundary; to?: WindowFrameBoundary },
+	) {}
+
+	getSQL(): SQL {
+		const fromSql = formatBoundary(this.spec.from);
+		if (this.spec.to) {
+			const toSql = formatBoundary(this.spec.to);
+			return sql`${sql.raw(this.type)} between ${fromSql} and ${toSql}`;
+		}
+		return sql`${sql.raw(this.type)} ${fromSql}`;
+	}
+}
+
+function validateFrameSpec(spec: { from: WindowFrameBoundary; to?: WindowFrameBoundary }): void {
+	if (spec.to) {
+		const rankFrom = getBoundaryRank(spec.from);
+		const rankTo = getBoundaryRank(spec.to);
+		if (rankFrom !== undefined && rankTo !== undefined && rankFrom > rankTo) {
+			throw new Error("Invalid window frame: 'from' boundary cannot be ordered after 'to' boundary");
+		}
+	}
+}
+
+export function rows(spec: { from: WindowFrameBoundary; to?: WindowFrameBoundary }): WindowFrame {
+	validateFrameSpec(spec);
+	return new WindowFrame('rows', spec)
